import {createWorkspaceAPI,normalizeCandles} from './workspace-api.js';
import {createHistoricalChart} from './historical-chart.js';
const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>[...root.querySelectorAll(q)];
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number.isFinite(n)?n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}):'—';
const pct=n=>Number.isFinite(n)?`${n>=0?'+':''}${n.toFixed(2)}%`:'—';
const num=n=>Number.isFinite(n)?Intl.NumberFormat('en-IN',{notation:'compact',maximumFractionDigits:1}).format(n):'—';
const cls=n=>!Number.isFinite(n)?'muted':n>=0?'green':'red';
const names={overview:'Market overview',scanner:'Stock scanner',watchlist:'Watchlist',methodology:'Methodology',admin:'Workspace settings'};
const sub={overview:'Price. Context. Conviction.',scanner:'A closer look at every stock in your universe.',watchlist:'The stocks that matter to you, in one place.',methodology:'Every signal has a reason. See exactly how it works.',admin:'Your workspace. Your settings. Your control.'};
function stored(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function store(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
let state={view:'overview',mode:'live',source:'public',marketSchedule:null,catalogue:null,aiPulse:null,aiPulseAt:0,aiMessages:[],aiBusy:false,aiReturnFocus:null,data:null,config:null,user:null,csrf:null,owner_exists:false,paused:false,timeframe:5,confirmed:false,direction:'bullish',symbol:'RELIANCE',watch:stored('zien-watchlist',['RELIANCE','INFY','HDFCBANK']),filter:'',sector:'all',sort:'score',chartCount:50,chartOffset:0,overlays:{vwap:true,zones:true,levels:false,volume:true},reduced:stored('zien-reduced',matchMedia('(prefers-reduced-motion: reduce)').matches),lastUpdate:0,fetching:false,modeError:null,revision:0};
let timer,toastTimer,chartDrag=null;
const candleCache=new Map(),pendingCandles=new Map();
const api=createWorkspaceAPI(()=>state,{onUnauthorized:()=>{state.user=null;state.csrf=null;applyBrand();if(state.view==='admin')renderAdmin()}});
const historyView=createHistoricalChart({api});
function openHistoryPanel(symbol){
 if($('#modal')?.open)dismissDialog();
 const stock=stocks().find(item=>item.symbol===symbol);
 historyView.open(symbol,stock?.name||'');
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}

function metric(s){if(!s||s.status==='failed'||s.stale||s.gap||!Number.isFinite(s.price))return null;const m=state.confirmed?s.confirmed:s.metrics;return Number.isFinite(m?.score)?m:null}

function selectedStock(){return state.data?.stocks.find(s=>s.symbol===state.symbol)||state.data?.stocks[0]}

function stocks(){return state.data?.stocks||[]}

function signal(s){const m=metric(s);return !m?'Unavailable':m.score>=state.config.rank_threshold&&m.score>50?'Bullish':m.score<=100-state.config.rank_threshold&&m.score<50?'Bearish':'Neutral'}

function spark(s,width=140,height=40){const values=s.candles?.map(c=>c.c)||[];if(values.length<2)return `<svg class="spark" viewBox="0 0 ${width} ${height}" aria-label="History unavailable"><path d="M0 ${height/2}H${width}" stroke="var(--border)" stroke-dasharray="3 4"/></svg>`;const lo=Math.min(...values),hi=Math.max(...values),d=values.map((v,i)=>`${i?'L':'M'}${(i/(values.length-1)*width).toFixed(1)},${(height-3-(v-lo)/(hi-lo||1)*(height-6)).toFixed(1)}`).join(' ');return `<svg class="spark" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" aria-hidden="true"><path d="${d}" fill="none" stroke="var(--${s.change>=0?'green':'red'})" stroke-width="1.5"/></svg>`}

function showModal(html,{wide=false,eyebrow='MARKETSCOPE'}={}){$('#modal').classList.toggle('wide',wide);$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}

function dismissDialog(){$('#modal').close();$('#modalBody').innerHTML='';}

function applyBrand(){const c=state.config;if(!c)return;$('#brand').textContent='Zien Quant';document.title='Zien Quant · India Terminal';$('#announcement').textContent=c.announcement||'';$('#announcement').hidden=!c.announcement;$('#watchCount').textContent=state.watch.length;$('#accountLabel').textContent=state.user?`${state.user.role} · ${state.user.email}`:'Sign in as owner';$$('#navigation button').forEach(b=>b.hidden=!c.navigation.includes(b.dataset.view))}

async function bootstrap({preserveView=false}={}){try{const b=await api('/api/bootstrap');Object.assign(state,{config:b.config,user:b.user,csrf:b.csrf,owner_exists:b.owner_exists,provider_status:b.provider_status,marketSchedule:b.market_schedule});if(!preserveView)state.timeframe=b.config.timeframe;applyBrand();renderTerminalContext();await refresh(true);if(state.view==='admin')renderAdmin()}catch(e){$('#mainContent').innerHTML=`<div class="panel empty"><h2>Workspace unavailable</h2><p>${safe(e.message)}</p><button class="button" id="retryBootstrap">Try again</button></div>`;$('#retryBootstrap').onclick=()=>bootstrap()}}

async function refresh(force=false){
 if(state.fetching||(state.paused&&!force)||!state.config||document.hidden)return;
 state.fetching=true;const revision=state.revision,mode=state.mode,tf=state.timeframe;
 try{const d=await api(`/api/market?mode=${mode}&timeframe=${tf}&source=public`);if(revision!==state.revision)return;state.data=d;state.modeError=null;state.lastUpdate=Date.now();if(d.schedule)state.marketSchedule=d.schedule;if(!stocks().some(s=>s.symbol===state.symbol))state.symbol=stocks()[0]?.symbol||'RELIANCE';for(const s of stocks()){const cached=candleCache.get(candleKey(s.symbol));if(cached)s.candles=cached.candles;}renderData();refreshTerminalContext();if(selectedStock())hydrateStock(state.symbol);if(state.detailSymbol&&state.detailSymbol!==state.symbol&&$('#modal').open)hydrateStock(state.detailSymbol)}
 catch(e){if(revision!==state.revision)return;state.modeError=e.message;state.data=null;renderData();renderTerminalContext()}
 finally{state.fetching=false;schedule();if(revision!==state.revision)refresh(true)}
}

function schedule(){clearTimeout(timer);timer=setTimeout(refresh,state.data?.session_state==='LIVE'?Math.max(3000,state.config?.refresh_ms||3000):30000)}

function renderStatus(){syncMotion();const d=state.data,historical=d&&d.session_state!=='LIVE';$('#autoMode').classList.toggle('selected',state.mode==='live');$('#previousMode').classList.toggle('selected',state.mode==='previous');$('#autoMode').setAttribute('aria-pressed',String(state.mode==='live'));$('#previousMode').setAttribute('aria-pressed',String(state.mode==='previous'));$('#modeLabel').textContent=state.modeError?'FEED UNAVAILABLE':d?.session_state==='CLOSED_TODAY'?`Closed session · ${d.session_date}`:historical?`Previous session · ${d.session_date||'date unavailable'}`:'Auto session · public source';$('#statusDot').className=`dot ${state.modeError?'red-dot':historical?'amber':''}`;$('#sessionStatus').textContent=state.modeError||d?.message||'Waiting for received market data';const stamps=stocks().map(s=>s.updated_at).filter(Number.isFinite),stamp=stamps.length?Math.max(...stamps):null;$('#updateTime').textContent=state.paused?'Paused':stamp?`Quote as of ${clock(stamp,true)} IST`:'No quote received';$('#pause').textContent=state.paused?'▷ Resume':'Ⅱ Pause';$('#footerStatus').textContent=state.modeError?'Feed unavailable':historical?'Stored real session':'Public candle research';$('#catalogueCount').textContent=state.catalogue?.total??state.config?.universe.length??'—'}

function navigate(view){if(!names[view])return;state.view=view;state.filter='';state.sector='all';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#pageCrumb').textContent=names[view];$('#pageTitle').textContent=names[view];$('#pageSubtitle').textContent=view==='overview'?state.config.tagline:sub[view];document.body.classList.remove('menu-open');history.replaceState(null,'',`#${view}`);renderView();}

function renderData(){renderStatus();if(['overview','scanner','watchlist'].includes(state.view)){if(state.view==='overview'&&$('#signalTerminal')&&stocks().length&&!state.modeError)updateOverview();else if((state.view==='scanner'||state.view==='watchlist')&&$('#stockCards')&&stocks().length)renderCards();else renderView()}if($('#detailChart'))renderDetailChart()}

function liveEmpty(){return `<section class="panel empty"><div class="empty-icon">⌁</div><h2>${state.modeError?'Market data is unavailable.':'No recorded session yet.'}</h2><p>${safe(state.modeError||'The backend has no received candles for this session. Prices, charts and setup levels stay unavailable until source data is received.')}</p><div class="actions"><button class="button primary" id="retryFeed">Retry connection</button><a class="button" href="/flow">Open Flow River ↗</a><button class="button" id="inspectSource">Inspect source status</button></div><p class="tiny muted">${state.data?.session_date?'Requested session: '+safe(state.data.session_date)+'. ':''}No generated price fallback. The exchange schedule and company search remain available.</p></section>`}

function renderView(){hideStockPeek();document.body.classList.toggle('terminal-edition',state.view==='overview');const root=$('#mainContent');if(['overview','scanner','watchlist'].includes(state.view)&&(!stocks().length||state.modeError)){root.innerHTML=liveEmpty();$('#retryFeed').onclick=()=>refresh(true);$('#inspectSource').onclick=showSourceDiagnostics;return}if(state.view==='overview')renderOverview();if(state.view==='scanner'||state.view==='watchlist')renderScanner();if(state.view==='methodology')renderMethodology();if(state.view==='admin')renderAdmin()}

function renderOverview(){
 hideStockPeek();document.body.classList.add('terminal-edition');
 $('#mainContent').innerHTML=`${state.mode==='live'&&state.data?.status!=='connected'?`<div class="notice">${safe(state.data?.message)} · Received observations remain labelled by session.</div>`:''}<section class="terminal-command"><div><span class="terminal-wordmark">◈</span><div><h2>India <span>Flow Terminal</span></h2><p>One workspace. Every source in view.</p></div></div><div class="terminal-settings"><div class="segmented"><button data-signal="provisional" class="${!state.confirmed?'active':''}">Provisional</button><button data-signal="confirmed" class="${state.confirmed?'active':''}">Confirmed</button></div><select id="terminalTimeframe" aria-label="Signal timeframe">${[1,5,15,60].map(t=>`<option value="${t}" ${state.timeframe===t?'selected':''}>${t===60?'1 hour':t+' min'}</option>`).join('')}</select></div></section><div id="terminalSummary" class="terminal-summary"></div><section id="signalTerminal" ${state.config.features.flow?'':'hidden'} class="signal-terminal" aria-label="Animated buy and sell signal terminal"><div class="trajectory-panel"><div class="terminal-panel-title"><span>01 / SESSION TRAJECTORIES</span><span class="trajectory-key"><i></i>UP <i></i>DOWN</span></div><div class="trajectory-caption"><strong>Follow the session.</strong><span>Price movement from session open</span></div><div id="trajectoryPlot" class="trajectory-plot" role="group" aria-label="Stock price trajectories, blue above the session open and red below it"></div><div class="trajectory-foot"><span><i class="motion-light"></i> <span id="trajectoryStatus">RECEIVED SESSION</span></span><span>Hover a line · Click to inspect ↗</span></div></div><div class="signal-clusters"><section class="signal-cluster buy-cluster"><div class="cluster-heading"><span><i></i> BUY SIDE <small>↗</small></span><b id="buyCount">—</b></div><div class="cluster-subtitle">Bullish score ≥ ${state.config.rank_threshold}</div><div id="buyTiles" class="signal-tiles"></div></section><section class="signal-cluster sell-cluster"><div class="cluster-heading"><span><i></i> SELL SIDE <small>↘</small></span><b id="sellCount">—</b></div><div class="cluster-subtitle">Bearish score ≤ ${100-state.config.rank_threshold}</div><div id="sellTiles" class="signal-tiles"></div></section></div><aside class="conviction-stack"><div class="terminal-panel-title"><span>03 / SIGNAL SPOTLIGHT</span><span>↗</span></div><div id="buySpotlights" class="spotlight-group"></div><div class="spotlight-divider"><span>BUY</span><i></i><span>SELL</span></div><div id="sellSpotlights" class="spotlight-group"></div></aside></section><div class="terminal-disclaimer" ${state.config.features.flow?'':'hidden'}><span>BLUE = ABOVE SESSION OPEN · RED = BELOW SESSION OPEN</span><span>${state.confirmed?'Confirmed on closed candles':'Provisional until candle close'} · Research signals, not trade execution</span></div><div class="lower-grid"><section class="panel chart-panel" id="mainChartPanel"></section><section class="panel"><div class="panel-head"><h2>Conviction leaders</h2><div class="rank-tabs"><button data-direction="bullish" class="${state.direction==='bullish'?'active':''}">Buy side ↗</button><button data-direction="bearish" class="${state.direction==='bearish'?'active':''}">Sell side ↘</button></div></div><div id="ranking"></div><button class="rank-foot full" data-view="scanner">Explore all ${stocks().length} stocks ↗</button></section></div>${state.config.features.sectors?`<section class="panel sector-panel"><div class="panel-head"><h2>Sector pulse</h2><span class="badge">${safe(state.data?.session_date||'RECEIVED SESSION')}</span></div><div id="sectors" class="sector-grid"></div></section>`:''}`;
 $('#terminalSummary').insertAdjacentHTML('afterend','<section id="dailyFormulaPanel" class="panel daily-formula-panel" aria-label="Best and worst stocks by daily formulas"></section>');
 $('.terminal-command h2').textContent='Market workspace';$('.terminal-command p').textContent='Session prices, charts and research signals';
 const signals=document.createElement('details');signals.className='signal-details';signals.open=state.signalsOpen===true;signals.innerHTML='<summary>Signal workspace <span>Session trajectories and filtered setups</span></summary>';
 $('#signalTerminal').before(signals);signals.append($('#signalTerminal'),$('.terminal-disclaimer'));
 signals.ontoggle=()=>{state.signalsOpen=signals.open;if(signals.open)drawAll()};
 $('#dailyFormulaPanel').after($('.lower-grid'));
 bindCommon();$('#terminalTimeframe').onchange=e=>setTimeframe(+e.target.value);$$('[data-signal]').forEach(b=>b.onclick=()=>{state.confirmed=b.dataset.signal==='confirmed';renderOverview()});$$('[data-direction]').forEach(b=>b.onclick=()=>{state.direction=b.dataset.direction;renderOverview()});updateOverview();
}

function updateOverview(){renderDailyRanking();updateSignalTerminal();renderRanking();renderSectors();renderMainChart();renderTerminalContext();syncMotion()}

function dailyRankingBrief(){
 const r=state.data?.daily_ranking;
 if(!r?.best||!r?.worst||r.session_date!==state.data?.session_date)return `Daily formula ranking for ${state.data?.session_date||'this session'} is unavailable. ${r?.reason||'At least two eligible stocks with complete closed-candle history for this session are required.'} ${r?.eligible_count??0} eligible; ${r?.excluded_count??stocks().length} excluded.`;
 return `${r.session_date}: best / strongest observed ${r.best.symbol}, directional score ${r.best.score}/100; worst / weakest observed ${r.worst.symbol}, score ${r.worst.score}/100. Candle closes: ${r.best.as_of} and ${r.worst.as_of}. Compared ${r.eligible_count} monitored equities in the 09:15–15:15 IST window. Closed 5-minute formulas: EMA, Supertrend, session VWAP, Wilder RSI, MACD and OBV. This descriptive score is an application heuristic, not a win probability or a prediction of the closing winners.`;
}

function renderDailyRanking(){
 const root=$('#dailyFormulaPanel');if(!root)return;
 const r=state.data?.daily_ranking;
 const valid=r?.session_date===state.data?.session_date&&r?.best&&r?.worst&&r.best.symbol!==r.worst.symbol&&Number.isFinite(r.best.score)&&Number.isFinite(r.worst.score);
 const ts=r?.tiers_summary||{bullish_count:0,bearish_count:0,normal_count:0};
 const card=(s,label,side)=>{
  const tier=s.rank_tier||(s.score>70?'BULLISH':s.score<50?'BEARISH':'NORMAL');
  const tierClass=tier==='BULLISH'?'tier-bullish':tier==='BEARISH'?'tier-bearish':'tier-normal';
  const layaPill=s.laya_decision?`<span class="laya-pill" title="Laya AI Decision">🤖 LAYA: <b>${safe(String(s.laya_decision.choice||'').toUpperCase())}</b> (${(Number(s.laya_decision.confidence||0)*100).toFixed(0)}%)</span>`:'';
  return `<button class="daily-rank-card ${side}" data-daily-stock="${safe(s.symbol)}" aria-label="Inspect ${safe(s.symbol)} daily formula details"><div class="daily-rank-header"><span>${label}</span><span class="tier-badge ${tierClass}">${tier}</span></div><div><strong>${safe(s.symbol)}</strong><b>${s.score.toFixed(2)}<small> / 100</small></b></div><p>${safe(s.name||s.symbol)}</p><div class="daily-meta-row"><small>Closed candle · ${safe(s.as_of||'timestamp unavailable')}</small>${layaPill}</div><div class="daily-components">${Object.entries(s.components||{}).map(([name,c])=>`<span>${safe(name.toUpperCase())}<b>${Number.isFinite(c.contribution)?c.contribution.toFixed(2):'—'}</b></span>`).join('')}</div></button>`;
 };
 root.innerHTML=`<div class="panel-head"><div><span class="eyebrow">PDF FORMULA ENGINE · CLOSED 5m</span><h2>Best &amp; worst of the session</h2></div><span class="badge">${safe(r?.session_date||state.data?.session_date||'UNAVAILABLE')}</span></div><p class="daily-description">Strongest and weakest observed directional scores across eligible monitored equities. Scores describe the received session.</p><div class="daily-tier-summary"><span>Ranking Tiers:</span> <strong class="green-text">Bullish (&gt;70): ${ts.bullish_count}</strong> · <strong class="muted-text">Normal (50–70): ${ts.normal_count}</strong> · <strong class="red-text">Bearish (&lt;50): ${ts.bearish_count}</strong></div>${valid?`<div class="daily-rank-grid">${card(r.best,'BEST / STRONGEST OBSERVED','buy')}${card(r.worst,'WORST / WEAKEST OBSERVED','sell')}</div>`:`<div class="notice" role="status">Ranking unavailable · ${safe(r?.reason||'Waiting for at least two stocks with complete closed-candle history.')}</div>`}<div class="daily-ranking-meta"><span>${r?.eligible_count??0} eligible · ${r?.excluded_count??stocks().length} excluded · ${safe(r?.formula_version||'pdf-quant-1')}</span><button class="text-button" id="dailyMethod">Inspect calculation ↗</button></div><details><summary>Weights, coverage &amp; exclusions</summary><p>EMA 20 · Supertrend 20 · VWAP 20 · RSI 15 · MACD 15 · OBV 10. Score = 50 + ½ × weighted signed components; each input is clamped to −1…1. Scores &gt;70 are Bullish, &lt;50 are Bearish, and 50–70 are Normal.</p><p>At least 35 closed bars, three session bars, complete session volume history, matching observation times and current data are required. The ranking always uses 5-minute candles, independently of the chart interval.</p><ul>${(r?.excluded||[]).slice(0,30).map(x=>`<li>${safe(x.symbol)}: ${safe(x.reason)}</li>`).join('')||'<li>No per-stock exclusions supplied.</li>'}</ul><p>Order-book, options-chain, dealer positioning and trained return forecasts are unavailable. Their inputs are not inferred from candles.</p></details>`;
 $('.daily-description',root).textContent='Common trading window · 09:15–15:15 IST · Closed 5m candles. Strongest and weakest observed scores across eligible monitored equities. Closing-auction bars are excluded.';
 $$('[data-daily-stock]',root).forEach(b=>b.onclick=()=>openDetail(b.dataset.dailyStock));
 $('#dailyMethod').onclick=()=>showModal(`<div class="prose"><h2>Auditable daily ranking</h2><p>${safe(r?.score_definition||'Score = 50 + 0.5 × sum(weight × signed component).')}</p><p>Technical formulas are taken from the supplied PDF, pages 7–14. The combined score is application policy and has not been calibrated against future returns. Classification tiers: Score &gt; 70 Bullish, Score &lt; 50 Bearish, 50–70 Normal. Optional CPR and Camarilla levels require a complete prior session; opening-range diagnostics require the full 09:15–09:30 IST window. Laya AI serves as the primary System 1 decision mechanism confirming technical trade bias.</p><p>${safe(dailyRankingBrief())}</p></div>`,{eyebrow:'PDF FORMULA METHODOLOGY'});
}

function renderRanking(){const sorted=stocks().filter(s=>metric(s)).sort((a,b)=>state.direction==='bullish'?metric(b).score-metric(a).score:metric(a).score-metric(b).score).slice(0,6);$('#ranking').innerHTML=`<table class="rank-table"><thead><tr><th>#</th><th>Stock</th><th>Price / change</th><th>Score</th></tr></thead><tbody>${sorted.map((s,i)=>`<tr data-stock="${safe(s.symbol)}" tabindex="0" role="button" aria-label="Open ${safe(s.symbol)} chart"><td>${String(i+1).padStart(2,'0')}</td><td><span class="stock-name">${safe(s.symbol)}</span><span class="stock-company">${safe(s.sector)}</span></td><td><span class="mono">${money(s.price)}</span><small class="${cls(s.change)}" style="display:block;font-size:9px;margin-top:2px">${pct(s.change)}</small></td><td><span class="score-pill ${state.direction==='bearish'?'bear':''}">${metric(s).score}</span></td></tr>`).join('')||'<tr><td colspan="4">No eligible signals for this timeframe.</td></tr>'}</tbody></table>`;$$('[data-stock]',$('#ranking')).forEach(b=>{b.onclick=()=>{state.symbol=b.dataset.stock;state.chartOffset=0;renderMainChart();hydrateStock(state.symbol)};b.onkeydown=e=>{if(e.key==='Enter')b.click()}})}

function renderSectors(){if(!$('#sectors'))return;const sectors={};stocks().forEach(s=>(sectors[s.sector]??=[]).push(s));$('#sectors').innerHTML=Object.entries(sectors).map(([name,ss])=>{const known=ss.filter(s=>Number.isFinite(s.change)),change=known.length?known.reduce((a,s)=>a+s.change,0)/known.length:null;return {name,ss,known,change}}).sort((a,b)=>(b.change??-Infinity)-(a.change??-Infinity)).map(({name,ss,known,change})=>`<button class="sector-card ${change!==null&&change<0?'negative':''}" data-sector="${safe(name)}"><span class="sector-name">${safe(name)}</span><strong class="${cls(change)}">${pct(change)}</strong><small>${known.length} of ${ss.length} with prior-close change</small><div class="sector-bar"><span style="width:${Number.isFinite(change)?Math.min(100,Math.abs(change)*22+10):0}%"></span></div></button>`).join('');$$('[data-sector]').forEach(b=>b.onclick=()=>{navigate('scanner');state.sector=b.dataset.sector;$('#sectorFilter').value=state.sector;renderCards()})}

function chartShell(s,id='mainChart'){return `<div class="panel-head"><div class="chart-heading"><span class="stock-avatar">${safe(s.symbol.slice(0,2))}</span><div><button class="symbol" data-detail="${safe(s.symbol)}">${safe(s.symbol)} <span class="muted tiny">↗</span></button><small>${safe(s.name)} · NSE</small></div></div><div class="chart-price">₹${money(s.price)}<small class="${cls(s.change)}">${pct(s.change)} <span class="muted tiny">session</span></small></div></div><div class="chart-toolbar"><div>${[1,5,15,60].map(tf=>`<button data-tf="${tf}" class="${state.timeframe===tf?'active':''}">${tf===60?'1h':`${tf}m`}</button>`).join('')}</div><div class="chart-indicators">${[['vwap','VWAP'],['zones','OB zones'],['levels','S/R'],['volume','Volume']].map(([k,n])=>`<button data-overlay="${k}" class="${state.overlays[k]?'active':''}">${n}</button>`).join('')}</div><div class="chart-actions"><button data-history="${safe(s.symbol)}" aria-label="Open historical price chart for ${safe(s.symbol)}">History ↗</button><button data-zoom="in" aria-label="Zoom chart in">+</button><button data-zoom="out" aria-label="Zoom chart out">−</button><button data-zoom="reset" aria-label="Reset chart">⤢</button></div></div><div id="${id}" class="chart-area" tabindex="0" aria-label="${safe(s.symbol)} candlestick chart. Use plus or minus to zoom; arrow keys to pan."></div><div class="chart-bottom"><span>RSI <b>${metric(s)?.rsi??'—'}</b></span><span>Relative volume <b>${metric(s)?.rvol??'—'}×</b></span><span>OI <b>${s.oi==null?'Not available':num(s.oi)}</b></span><span style="margin-left:auto">${state.confirmed?'Closed-candle view':s.candles.at(-1)?.closed?'All received candles closed':'Provisional · open candle'}</span></div>`}

function bindChart(root,s){
 const current=()=>stocks().find(stock=>stock.symbol===s.symbol)||s;
 $$('[data-tf]',root).forEach(b=>b.onclick=()=>setTimeframe(+b.dataset.tf));
 $$('[data-overlay]',root).forEach(b=>b.onclick=()=>{state.overlays[b.dataset.overlay]=!state.overlays[b.dataset.overlay];renderMainChart();renderDetailChart()});
 $$('[data-zoom]',root).forEach(b=>b.onclick=()=>{if(b.dataset.zoom==='reset'){state.chartCount=50;state.chartOffset=0}else state.chartCount=Math.max(10,Math.min(375,Math.round(state.chartCount*(b.dataset.zoom==='in'?.75:1.3))));drawAll()});
 $$('[data-detail]',root).forEach(b=>b.onclick=()=>openDetail(s.symbol));$$('[data-history]',root).forEach(b=>b.onclick=()=>openHistoryPanel(s.symbol));
 const area=$('.chart-area',root);
 area.onwheel=e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();state.chartCount=Math.max(10,Math.min(375,state.chartCount+(e.deltaY>0?5:-5)));drawAll()};
 area.onkeydown=e=>{if(['+','=','-','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')state.chartOffset=Math.min(Math.max(0,current().candles.length-1),state.chartOffset+5);else if(e.key==='ArrowRight')state.chartOffset=Math.max(0,state.chartOffset-5);else state.chartCount=Math.max(10,Math.min(375,state.chartCount+(e.key==='-'?5:-5)));drawAll()}};
 area.onpointerdown=e=>{chartDrag={x:e.clientX,offset:state.chartOffset};area.setPointerCapture(e.pointerId)};area.onpointerup=()=>{chartDrag=null};
 area.onpointermove=e=>{if(chartDrag&&e.buttons){state.chartOffset=Math.max(0,Math.min(Math.max(0,current().candles.length-10),chartDrag.offset+Math.round((chartDrag.x-e.clientX)/8)));drawAll();return}showChartTip(area,current(),e)};
 area.onpointerleave=()=>{$('.chart-tip',area)?.remove();chartDrag=null};
}

function renderMainChart(){const root=$('#mainChartPanel'),s=selectedStock();if(!root||!s)return;const old=root.dataset.symbol===s.symbol&&root.dataset.tf===String(state.timeframe);if(!old){root.innerHTML=chartShell(s);root.dataset.symbol=s.symbol;root.dataset.tf=state.timeframe;bindChart(root,s)}else{ $('.chart-price',root).innerHTML=`₹${money(s.price)}<small class="${cls(s.change)}">${pct(s.change)} <span class="muted tiny">session</span></small>`;$$('[data-overlay]',root).forEach(b=>b.classList.toggle('active',state.overlays[b.dataset.overlay]));$('.chart-bottom',root).innerHTML=`<span>RSI <b>${metric(s)?.rsi??'—'}</b></span><span>Relative volume <b>${metric(s)?.rvol??'—'}×</b></span><span>OI <b>${s.oi==null?'Not available':num(s.oi)}</b></span><span style="margin-left:auto">${state.confirmed?'Closed-candle view':s.candles.at(-1)?.closed?'All received candles closed':'Provisional · open candle'}</span>`}drawChart($('#mainChart'),s)}

function drawAll(){const s=selectedStock();if(s&&$('#mainChart'))drawChart($('#mainChart'),s);renderDetailChart();historyView.resize()}

function chartBars(s){const cc=state.confirmed?s.candles.filter(c=>c.closed===true):s.candles;const offset=Math.min(state.chartOffset,Math.max(0,cc.length-1)),end=cc.length-offset;return cc.slice(Math.max(0,end-state.chartCount),end)}

function showChartTip(area,s,e){const rect=area.getBoundingClientRect(),bars=chartBars(s),i=Math.max(0,Math.min(bars.length-1,Math.floor((e.clientX-rect.left-14)/(rect.width-78)*bars.length))),c=bars[i];if(!c)return;let tip=$('.chart-tip',area);if(!tip){tip=document.createElement('div');tip.className='chart-tip';area.append(tip)}tip.textContent=`${new Date(c.t*1000).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:false})} IST · O ${money(c.o)} H ${money(c.h)} L ${money(c.l)} C ${money(c.c)} · V ${num(c.v)} · ${c.closed?'Closed':'Open'}`;}

function openDetail(symbol){hideStockPeek();state.detailSymbol=symbol;const s=stocks().find(s=>s.symbol===symbol);if(!s)return;showModal(`<section class="panel" id="detailPanel">${chartShell(s,'detailChart')}</section><div class="detail-context"><div>${sourceBadge(s)}<span class="quote-time">Quote ${clock(s.updated_at,true)} IST</span></div><button class="button" id="detailWatch">${state.watch.includes(symbol)?'★ Remove from':'☆ Add to'} watchlist</button></div><div id="detailSetup">${setupPanel(s)}</div><section class="panel source-audit"><div class="panel-head"><h2>Data provenance</h2><span class="badge">${safe(sourceTitle(s.source))}</span></div>${comparisonMarkup(s)}<p>${safe(s.sector)} · ${s.stale?'Stale observation · ':''}${s.gap?'History gap · ':''}${state.data?.session_state==='LIVE'?'Received public candles':'Stored real-session research'}. Indicator values do not establish exchange freshness.</p></section><section class="panel stock-ai"><div class="panel-head"><h2>Laya research briefing</h2><button class="button" id="analyzeStock">Explain this stock ↗</button></div><div id="stockAiText"><p class="muted">Request an explanation of the received snapshot. Local-model prose is labelled separately.</p></div></section>`,{wide:true,eyebrow:'ZIEN QUANT / COMPANY RESEARCH'});bindChart($('#detailPanel'),s);$('#detailWatch').onclick=()=>{toggleWatch(symbol);openDetail(symbol)};$('#analyzeStock').onclick=()=>analyzeStock(symbol);drawChart($('#detailChart'),s);hydrateStock(symbol)}

function renderDetailChart(){const s=stocks().find(s=>s.symbol===state.detailSymbol);if(!s||!$('#detailChart'))return;const root=$('#detailPanel');if(!root.dataset.tf||root.dataset.tf!==String(state.timeframe)){root.innerHTML=chartShell(s,'detailChart');root.dataset.tf=state.timeframe;bindChart(root,s)}$$('[data-overlay]',root).forEach(b=>b.classList.toggle('active',state.overlays[b.dataset.overlay]));$('.chart-price',root).innerHTML=`₹${money(s.price)}<small class="${cls(s.change)}">${pct(s.change)}</small>`;drawChart($('#detailChart'),s);if($('#detailSetup'))$('#detailSetup').innerHTML=setupPanel(s)}

function setTimeframe(tf){if(![1,5,15,60].includes(tf)||tf===state.timeframe)return;state.revision++;state.timeframe=tf;state.chartOffset=0;state.data=null;state.aiPulse=null;state.modeError=null;dismissDialog();renderStatus();renderView();if(!state.fetching)refresh(true)}

function setMode(mode){if(!['live','previous'].includes(mode)||state.mode===mode)return;state.revision++;state.mode=mode;state.data=null;state.aiPulse=null;state.aiPulseAt=0;state.modeError=null;state.paused=false;state.aiMessages=[];dismissDialog();renderStatus();renderView();renderTerminalContext();if(!state.fetching)refresh(true)}

function toggleWatch(symbol){state.watch=state.watch.includes(symbol)?state.watch.filter(s=>s!==symbol):[...state.watch,symbol];store('zien-watchlist',state.watch);$('#watchCount').textContent=state.watch.length;toast(state.watch.includes(symbol)?`${symbol} added to watchlist`:`${symbol} removed from watchlist`);if($('#stockCards'))renderCards()}

function renderScanner(){$('#mainContent').innerHTML=`<section class="panel"><div class="scanner-tools"><input id="stockFilter" aria-label="Filter stocks" placeholder="Search symbol or company…" value="${safe(state.filter)}"><select id="sectorFilter" aria-label="Filter by sector"><option value="all">All sectors</option>${[...new Set(stocks().map(s=>s.sector))].sort().map(s=>`<option ${s===state.sector?'selected':''}>${safe(s)}</option>`).join('')}</select><select id="sortFilter" aria-label="Sort stocks"><option value="score">Highest score</option><option value="change">Highest change</option><option value="bear">Lowest score</option><option value="name">Symbol A–Z</option></select><span class="badge" style="margin-left:auto;align-self:center">${state.data?.session_state==='LIVE'?'PUBLIC · RESEARCH ONLY':'STORED REAL SESSION'}</span></div></section><div id="stockCards" class="stocks-grid"></div>`;$('#stockFilter').oninput=e=>{state.filter=e.target.value;renderCards()};$('#sectorFilter').onchange=e=>{state.sector=e.target.value;renderCards()};$('#sortFilter').value=state.sort;$('#sortFilter').onchange=e=>{state.sort=e.target.value;renderCards()};renderCards()}

function renderCards(){let ss=stocks().filter(s=>(state.view!=='watchlist'||state.watch.includes(s.symbol))&&(state.sector==='all'||s.sector===state.sector)&&`${s.symbol} ${s.name}`.toLowerCase().includes(state.filter.toLowerCase()));ss.sort((a,b)=>state.sort==='name'?a.symbol.localeCompare(b.symbol):state.sort==='change'?(b.change||0)-(a.change||0):state.sort==='bear'?(metric(a)?.score??50)-(metric(b)?.score??50):(metric(b)?.score??50)-(metric(a)?.score??50));$('#stockCards').innerHTML=ss.map(s=>`<article class="panel stock-card" data-card="${safe(s.symbol)}" tabindex="0" aria-label="Open ${safe(s.symbol)} details"><header><span class="stock-avatar">${s.symbol.slice(0,2)}</span><div><span class="stock-name">${safe(s.symbol)}</span><span class="stock-company">${safe(s.name)}</span></div><button data-watch="${safe(s.symbol)}" class="${state.watch.includes(s.symbol)?'saved':''}" aria-label="${state.watch.includes(s.symbol)?'Remove':'Add'} ${safe(s.symbol)} ${state.watch.includes(s.symbol)?'from':'to'} watchlist">${state.watch.includes(s.symbol)?'★':'☆'}</button></header><div class="price-line"><b>₹${money(s.price)}</b><span class="${cls(s.change)}">${pct(s.change)}</span></div>${spark(s)}<div class="card-provenance">${sourceBadge(s)}</div><footer><span>Score <strong>${metric(s)?.score??'—'}</strong></span><span>RSI <strong>${metric(s)?.rsi??'—'}</strong></span><span class="${(metric(s)?.score??50)>=50?'green':'red'}">${signal(s)}</span></footer></article>`).join('')||`<div class="panel empty" style="grid-column:1/-1"><div class="empty-icon">☆</div><h2>${state.view==='watchlist'?'Build your watchlist':'No matching stocks'}</h2><p>${state.view==='watchlist'?'Star a stock in the scanner or stock details to keep it here.':'Try another symbol or sector.'}</p><button class="button" data-view="scanner">Open stock scanner</button></div>`;$$('[data-card]').forEach(c=>{c.onclick=()=>openDetail(c.dataset.card);c.onkeydown=e=>{if(e.key==='Enter')c.click()}});$$('[data-watch]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleWatch(b.dataset.watch)});bindCommon()}

function showSearch(){
 showModal('<div class="search-heading"><h2>Find your next focus.</h2><span class="badge">NSE MASTER</span></div><p>Search companies and symbols. Tracking a new stock updates the owner’s market universe.</p><input id="searchInput" aria-label="Search all NSE stocks" placeholder="Symbol or company name…" autocomplete="off"><div id="searchMeta" class="search-meta">Searching the instrument catalogue…</div><div id="searchResults" class="search-results"></div>',{eyebrow:'COMMAND SEARCH · ⌘ / CTRL K'});
 let searchSequence=0,searchTimer;
 const update=async()=>{
  const input=$('#searchInput');if(!input)return;const q=input.value.trim(),seq=++searchSequence;
  let result;
  try{result=await api('/api/stocks/database?q='+encodeURIComponent(q)+'&limit=30')}catch{result={stocks:stocks().filter(s=>`${s.symbol} ${s.name} ${s.sector}`.toLowerCase().includes(q.toLowerCase())),total:stocks().length,source:'Selected universe'}}
  if(seq!==searchSequence||!$('#searchInput'))return;
  const rows=result.stocks||result.results||[];state.catalogue={...state.catalogue,...result};
  $('#searchMeta').textContent=`${Number(result.total??rows.length).toLocaleString('en-IN')} catalogue entries · ${result.source||'NSE equities'} · ${state.config.universe.length} tracked`;
  $('#searchResults').innerHTML=rows.map(s=>{const live=stocks().find(v=>v.symbol===s.symbol),tracked=state.config.universe.includes(s.symbol);return `<button class="search-result" data-result="${safe(s.symbol)}" data-tracked="${tracked}"><span class="stock-avatar">${safe(s.symbol.slice(0,2))}</span><span><strong>${safe(s.symbol)}</strong><small>${safe(s.name)} · ${safe(s.exchange||'NSE')}</small></span><span class="result-price">${live?'₹'+money(live.price):tracked?'Tracked':'Track ↗'}<small class="${live?cls(live.change):'muted'}">${live?pct(live.change):tracked?'Waiting for data':'Owner access'}</small></span></button>`}).join('')||'<p style="padding:20px 0">No instruments match this search.</p>';
  $$('[data-result]').forEach(b=>b.onclick=async()=>{
   const symbol=b.dataset.result;
   if(stocks().some(s=>s.symbol===symbol))return openDetail(symbol);
   if(b.dataset.tracked==='true')return toast(`${symbol} is tracked. Waiting for source data.`);
   if(state.user?.role!=='owner'){toast('Sign in as owner to add tracked stocks.');return showLogin()}
   b.disabled=true;
   try{await api('/api/stocks/track',{method:'POST',body:{symbol}});const config=await api('/api/bootstrap');state.config=config.config;state.allSymbols=[...new Set([...(state.allSymbols||[]),symbol])];await refresh(true);toast(`${symbol} added to tracking`);if(stocks().some(s=>s.symbol===symbol))openDetail(symbol);else update()}catch(e){toast(e.message);b.disabled=false}
  });
 };
 $('#searchInput').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(update,180)};update();$('#searchInput').focus();
}


function renderMethodology(){$('#mainContent').innerHTML=`<div class="method-grid"><article class="panel prose"><span class="plan-kicker">TRANSPARENT CALCULATIONS</span><h2>Inspect the signal.</h2><p>This workspace preserves the reference design and uses the repository’s existing normalized technical engine. Four individually clamped components combine EMA separation, five-bar momentum, session VWAP distance and RSI.</p><div class="formula">Score = round(50 + (35 × trend + 30 × momentum + 20 × VWAP + 15 × RSI) / 2)</div><p>Each component is normalized into −1…1. Defaults are EMA 9/21, rolling RSI 14, and bullish/bearish cutoffs ${state.config.rank_threshold}/${100-state.config.rank_threshold}. EMA starts at the first close. VWAP uses typical-price volume and resets by IST session date. ATR14 uses Wilder smoothing.</p><h3>Risk filter</h3><p>Setup cards require positive ordered entry/stop/target levels, matching direction and at least 1:1.5 reward/risk. Rejected setups have no displayed entry or targets. Grades express rule conditions; they are not measured win probabilities.</p><h3>Confirmation</h3><p>The current backend does not expose independently computed confirmed setup plans. Those plans are withheld when inspecting confirmed indicators. Indicator warm-up and unavailable fields stay explicit.</p><h3>Order blocks</h3><p>A close outside the previous five-bar range anchors a zone to the preceding opposing candle. Later closed-bar invalidation removes that zone. This price/volume heuristic does not establish institutional participation.</p><h3>Data provenance</h3><p>Blue and red trajectories show movement above and below the session open. Signal-card classifications use technical score and risk filters, so their meaning can differ. The plot uses received percentage samples without inventing exact intrabar timestamps. Sector performance averages only received tracked companies.</p><p>Historical charts filter received candles to the returned session date. No generated or interpolated price fallback is used. Public candle availability and latency vary. The terminal does not place orders or establish profitable performance.</p></article><aside class="panel prose"><h2>Session behavior</h2><p><b>Auto session</b> follows the backend’s live, closed-today or stored-session state.</p><p><b>Previous session</b> asks the backend for its stored real session and displays the exact date returned.</p><p>Unknown data remains unavailable. The original <a href="/flow">Flow River ↗</a> and its stage engine remain accessible.</p><button class="button" id="methodSources">Inspect sources</button></aside></div>`;$('#methodSources').onclick=showSourceDiagnostics;bindCommon()}

function showLogin(){
 if(state.user){
  showModal(`<div class="account-header"><span class="eyebrow">SIGNED IN</span><h2>Your account</h2><p>${safe(state.user.email)} · ${safe(state.user.role)}</p></div><div class="actions"><button class="button primary" id="openOwner">Workspace settings</button><button class="button" id="signout">Sign out</button></div>`);
  $('#signout').onclick=async()=>{try{await api('/api/logout',{method:'POST',body:{}});state.user=null;state.csrf=null;state.aiMessages=[];dismissDialog();await bootstrap({preserveView:true});toast('Signed out')}catch(e){toast(e.message)}};
  $('#openOwner').onclick=()=>{dismissDialog();navigate('admin')};return;
 }
 showModal(`<div class="account-header"><span class="eyebrow">ZIEN QUANT</span><h2>Sign in to your workspace</h2><p>${state.owner_exists?'Use your owner email and password. We’ll ask for your authenticator code if it is enabled.':'An owner account has not been set up. Run python manage.py init-owner locally to enrol your account.'}</p></div><form id="loginForm"><label class="field">Email<input name="email" type="email" autocomplete="username" maxlength="254" required></label><label class="field">Password<div class="password-field"><input name="password" type="password" autocomplete="current-password" maxlength="1024" required><button type="button" id="togglePassword" aria-label="Show password">Show</button></div></label><div id="mfaStep" hidden><label class="field">Authenticator code<input name="totp_code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" disabled aria-describedby="mfaHelp"></label><p id="mfaHelp" class="muted tiny">Enter the six-digit code from the authenticator app linked to this account.</p></div><button class="button primary full" type="submit" ${state.owner_exists?'':'disabled'}>Continue</button><p id="loginError" class="form-error" role="alert"></p></form><button class="text-button account-help" id="accountRecovery">Lost access to your authenticator?</button><div id="recoveryHelp" class="notice" hidden><strong>Recover on this computer</strong><p>In a terminal opened in this project, run <code>python manage.py reset-mfa</code>. Verify your existing owner password, then enrol a replacement authenticator. Existing account data stays intact.</p><p>Never share your password or setup key in chat.</p></div>`,{eyebrow:'PRIVATE ACCOUNT'});
 const form=$('#loginForm'),password=$('[name=password]',form),email=$('[name=email]',form),code=$('[name=totp_code]',form);
 $('#togglePassword').onclick=()=>{const visible=password.type==='password';password.type=visible?'text':'password';$('#togglePassword').textContent=visible?'Hide':'Show';$('#togglePassword').setAttribute('aria-label',visible?'Hide password':'Show password')};
 $('#accountRecovery').onclick=()=>{$('#recoveryHelp').hidden=!$('#recoveryHelp').hidden;$('#accountRecovery').setAttribute('aria-expanded',String(!$('#recoveryHelp').hidden))};
 const resetStep=()=>{if(!$('#mfaStep').hidden){$('#mfaStep').hidden=true;code.disabled=true;code.required=false;code.value='';$('button[type=submit]',form).textContent='Continue'}};
 email.oninput=resetStep;password.oninput=resetStep;
 form.onsubmit=async e=>{
  e.preventDefault();const button=$('button[type=submit]',form);if(button.disabled)return;
  button.disabled=true;button.textContent='Signing in…';$('#loginError').textContent='';
  try{
   const r=await api('/api/login',{method:'POST',body:{email:email.value.trim(),password:password.value,totp_code:code.disabled?'':code.value.trim()}});
   password.value='';code.value='';state.csrf=r.csrf_token;dismissDialog();await bootstrap({preserveView:true});toast('Signed in');
  }catch(err){
   if(!$('#loginForm'))return;
   if(err.requires_mfa){$('#mfaStep').hidden=false;code.disabled=false;code.required=true;code.value='';code.focus();$('#loginError').textContent=err.status===400?'Enter your authenticator code to finish signing in.':err.message}
   else $('#loginError').textContent=err.status===429?`Too many attempts. Try again in ${err.retry_after||60} seconds.`:err.message;
  }finally{button.disabled=false;button.textContent=code.disabled?'Continue':'Verify & sign in'}
 };
}

async function renderAdmin(){const owner=state.user?.role==='owner',c=state.config;$('#mainContent').innerHTML=`<section class="panel prose"><span class="plan-kicker">ZIEN QUANT / OWNER CONSOLE</span><h2>Your workspace. Your control.</h2><p>Market data and protected settings use the existing local Python service. Display preferences and watchlists stay in your browser.</p>${!owner?`<div class="notice">Owner sign-in is required to save protected server configuration.</div><button class="button primary" id="adminLogin">${state.user?'Account details':'Sign in as owner'}</button>`:`<form id="settingsForm"><div class="form-grid">${[['rank_threshold','Bullish score cutoff',51,95],['ema_fast','Fast EMA period',2,50],['ema_slow','Slow EMA period',5,200],['rsi_period','RSI period',2,100],['refresh_ms','Refresh interval (ms)',3000,30000]].map(([key,label,min,max])=>`<label class="field">${label}<input name="${key}" type="number" value="${c[key]}" min="${min}" max="${max}" required></label>`).join('')}<label class="field">Default candle interval<select name="timeframe">${[1,5,15,60].map(tf=>`<option value="${tf}" ${tf===c.timeframe?'selected':''}>${tf===60?'1 hour':tf+' minutes'}</option>`).join('')}</select></label></div><button class="button primary">Save versioned configuration</button><p id="configError" class="form-error" role="alert"></p></form><div class="actions"><button class="button" id="historyButton">Configuration history</button><button class="button" id="backupButton">Create database backup</button><button class="button" id="journalButton">Inspect recorded signal statistics</button></div>`}<h3>Data and analysis</h3><p>Public received candles and persistent real-session snapshots power this version. Optional local Ollama commentary is validated and labelled separately from deterministic rules. Broker account authorization is not connected here.</p><div class="actions"><button class="button" id="adminSources">Source diagnostics</button><a class="button" href="/flow">Original Flow River ↗</a></div><div id="adminOutput" role="status"></div></section>`;$('#adminLogin')?.addEventListener('click',showLogin);$('#adminSources').onclick=showSourceDiagnostics;$('#settingsForm')?.addEventListener('submit',async e=>{e.preventDefault();const patch=Object.fromEntries([...new FormData(e.currentTarget)].map(([k,v])=>[k,Number(v)]));try{await saveConfig(patch);toast('Configuration saved as a new version')}catch(err){$('#configError').textContent=err.message}});$('#historyButton')?.addEventListener('click',showHistory);$('#backupButton')?.addEventListener('click',async()=>{try{await api('/api/backup',{method:'POST',body:{}});toast('Protected database backup created')}catch(e){toast(e.message)}});$('#journalButton')?.addEventListener('click',async()=>{try{const d=await api('/api/signals/stats?include_gated=1');if($('#adminOutput'))$('#adminOutput').innerHTML=`<h3>Recorded signal outcomes</h3><div class="health-row"><span>Total signals</span><strong>${Number(d.total_signals)||0}</strong></div><div class="health-row"><span>Observed win rate</span><strong>${d.total_signals?Number(d.win_rate_pct||0).toFixed(1)+'%':'No closed observations'}</strong></div><p class="muted tiny">Recorded outcomes do not include brokerage execution, transaction costs or slippage.</p>`}catch(e){toast(e.message)}});bindCommon()}

async function saveConfig(patch){if(state.user?.role!=='owner')throw Error('Owner authentication required.');await api('/api/config',{method:'POST',body:patch});const b=await api('/api/bootstrap');state.config=b.config;state.csrf=b.csrf;state.revision++;applyBrand();await refresh(true)}

async function showHistory(){try{const r=await api('/api/config/history');showModal(`<h2>Configuration history</h2><p>Versioned records are read from the private server.</p>${r.versions.map(v=>`<div class="health-row"><span>Version ${safe(v.id)}</span><strong>${safe(v.created_at||'Timestamp unavailable')}</strong></div>`).join('')||'<p>No versions recorded.</p>'}`)}catch(e){toast(e.message)}}

function download(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

function bindCommon(){$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view))}

function syncMotion(){
 const stale=state.lastUpdate&&Date.now()-state.lastUpdate>10000;
 document.body.classList.toggle('motion-idle',state.paused||document.hidden||Boolean(state.modeError)||Boolean(stale)||(state.mode==='live'&&state.data?.status!=='connected'));
 document.body.classList.toggle('focus-view',localStorage.getItem('marketscope-focus')==='on');
 if($('#heroActivity')&&state.paused)$('#heroActivity').textContent='Replay paused';
 $('#motion')?.setAttribute('aria-pressed',String(state.reduced));
 $('#motion')?.setAttribute('title',state.reduced?'Enable ambient motion':'Reduce motion');
}

function volumeFingerprint(s){
 const bars=s.candles.slice(-20),max=Math.max(...bars.map(b=>b.v),1);
 return `<svg viewBox="0 0 140 50" aria-label="Last 20 candle volumes" role="img">${bars.map((b,i)=>`<rect x="${i*7}" y="${48-b.v/max*42}" width="4.5" height="${b.v/max*42}" fill="currentColor" opacity="${.25+i/30}"/>`).join('')}</svg>`;
}

function miniSignalChart(s){
 const bars=s.candles.slice(-30);if(!bars.length)return '<span class="muted">History unavailable</span>';const min=Math.min(...bars.map(c=>c.l)),max=Math.max(...bars.map(c=>c.h)),range=max-min||1;
 const y=p=>8+(max-p)/range*63;
 return `<svg viewBox="0 0 190 85" role="img" aria-label="${safe(s.symbol)} recent candles"><path d="M0 21H190M0 43H190M0 64H190" stroke="currentColor" stroke-opacity=".12" stroke-dasharray="2 3"/>${bars.map((b,i)=>`<line x1="${i*6+5}" x2="${i*6+5}" y1="${y(b.h)}" y2="${y(b.l)}" stroke="currentColor" opacity=".7"/><rect x="${i*6+3.5}" y="${Math.min(y(b.o),y(b.c))}" width="3" height="${Math.max(1,Math.abs(y(b.o)-y(b.c)))}" fill="currentColor" opacity="${b.c>=b.o?.9:.4}"/>`).join('')}<line x1="0" x2="190" y1="${y(bars.at(-1).c)}" y2="${y(bars.at(-1).c)}" stroke="currentColor" stroke-dasharray="3 3" opacity=".45"/></svg>`;
}

function signalTile(s,side,index){
 const m=metric(s);
 return `<button class="signal-tile ${side}" data-terminal-stock="${safe(s.symbol)}" style="--tile-delay:${index*-.4}s" aria-label="Open ${safe(s.symbol)} ${side} signal details"><div class="tile-corners" aria-hidden="true"></div><div class="tile-top"><strong>${safe(s.symbol)}</strong><span>${String(index+1).padStart(2,'0')}</span></div><small class="tile-sector">${safe(s.sector)}</small><div class="tile-signal"><span>${side==='buy'?'BUY SIGNAL':'SELL SIGNAL'}</span><b>${m.score}</b></div><div class="volume-fingerprint">${volumeFingerprint(s)}</div><div class="tile-price"><b>₹${money(s.price)}</b><span>${pct(s.change)}</span></div><div class="tile-footer">RSI ${m.rsi}<span>RVOL ${m.rvol??'—'}×</span></div><div class="tile-source">${sourceBadge(s)}</div></button>`;
}

function spotlight(s,side){
 const m=metric(s),zone=(m.zones||[]).filter(z=>z.direction===(side==='buy'?'bullish':'bearish')).at(-1);
 return `<button class="signal-spotlight ${side}" data-terminal-stock="${safe(s.symbol)}" aria-label="Open ${safe(s.symbol)} spotlight"><div class="spotlight-top"><strong>${safe(s.symbol)}</strong><span>${state.confirmed?'CONFIRMED':'PROVISIONAL'}</span></div><div class="spotlight-middle"><div><span class="direction-badge">${side==='buy'?'BUY ↗':'SELL ↘'}</span><b class="spotlight-price">₹${money(s.price)}</b><small>${pct(s.change)} <em>session</em></small><span class="spotlight-score">SCORE <b>${m.score}</b> / 100</span></div><div class="spotlight-chart">${miniSignalChart(s)}</div></div><div class="spotlight-levels"><span>SUPPORT<b>${money(m.support)}</b></span><span>VWAP<b>${money(m.vwap)}</b></span><span>RESISTANCE<b>${money(m.resistance)}</b></span></div><div class="signal-strength"><i style="width:${side==='buy'?m.score:100-m.score}%"></i></div><div class="spotlight-zone">${zone?`OB ZONE ${money(zone.low)} – ${money(zone.high)}`:'NO ACTIVE MATCHING ORDER BLOCK'}<span>DETAILS ↗</span></div><div class="spotlight-plan">${compactPlan(s)}</div></button>`;
}

function updateTerminalList(id,ss,side,large=false){
 const container=$(id);const next=ss.map(s=>s.symbol).join(',');
 const oldPositions=new Map($$('[data-terminal-stock]',container).map(b=>[b.dataset.terminalStock,b.getBoundingClientRect().top]));
 container.innerHTML=ss.map((s,i)=>large?spotlight(s,side):signalTile(s,side,i)).join('')||`<div class="no-signal"><span>—</span>No eligible ${side}-side signals<br><small>Try another timeframe or review the score threshold.</small></div>`;
 $$('[data-terminal-stock]',container).forEach(b=>{b.onclick=()=>openDetail(b.dataset.terminalStock);const previous=oldPositions.get(b.dataset.terminalStock);if(container.dataset.order!==next&&previous!==undefined&&!state.reduced&&!state.paused&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const delta=previous-b.getBoundingClientRect().top;if(delta)b.animate([{transform:`translateY(${delta}px)`},{transform:'translateY(0)'}],{duration:850,easing:'cubic-bezier(.2,.7,.2,1)'});}});
 container.dataset.order=next;
}

function updateSignalTerminal(){if(!$('#signalTerminal'))return;const ss=stocks(),eligible=ss.filter(s=>{const m=metric(s),p=normalizedSetup(s);return m&&p.entry!=null&&p.stop_loss!=null&&p.risk_reward>=1.5&&!p.type.startsWith('avoid')&&!state.confirmed}),buy=eligible.filter(s=>metric(s).score>=state.config.rank_threshold&&s.setup?.direction==='long').sort((a,b)=>metric(b).score-metric(a).score),sell=eligible.filter(s=>metric(s).score<=100-state.config.rank_threshold&&s.setup?.direction==='short').sort((a,b)=>metric(a).score-metric(b).score);$('#buyCount').textContent=`${buy.length} SETUPS`;$('#sellCount').textContent=`${sell.length} SETUPS`;const bullish=ss.filter(s=>signal(s)==='Bullish').length,bearish=ss.filter(s=>signal(s)==='Bearish').length;$('#terminalSummary').innerHTML=`<span><i class="buy-dot"></i><b>${bullish}</b> BULLISH BIAS</span><span><i class="sell-dot"></i><b>${bearish}</b> BEARISH BIAS</span><span><b>${ss.length-bullish-bearish}</b> NEUTRAL / UNAVAILABLE</span><span class="summary-universe">${ss.length} TRACKED <i>·</i> SELECTED UNIVERSE</span>`;$('#trajectoryStatus').textContent=state.paused?'PAUSED':state.data?.session_state==='LIVE'?'PUBLIC SOURCE · RESEARCH':`REAL SESSION · ${state.data?.session_date||'DATE UNAVAILABLE'}`;updateTerminalList('#buyTiles',buy.slice(0,8),'buy');updateTerminalList('#sellTiles',sell.slice(0,8),'sell');updateTerminalList('#buySpotlights',buy.slice(0,3),'buy',true);updateTerminalList('#sellSpotlights',sell.slice(0,3),'sell',true);drawTrajectories(ss)}

function drawTrajectories(ss){
 const root=$('#trajectoryPlot');if(!root)return;const W=560,H=800,left=51,right=445,top=36,bottom=758,mid=(top+bottom)/2;
 const series=ss.map(s=>({s,values:s.trajectory||[]})).filter(v=>v.values.filter(Number.isFinite).length>1&&Number.isFinite(v.s.price)&&v.s.status!=='failed');
 if(!series.length){root.innerHTML='<div class="chart-empty">No received trajectory series for this session.</div>';return}
 const bound=Math.max(2,Math.ceil(Math.max(...series.flatMap(v=>v.values.filter(Number.isFinite).map(Math.abs))))),y=v=>mid-v/bound*(mid-top),x=r=>left+r*(right-left);
 let svg=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="Received percentage trajectories from session open"><defs><pattern id="terminalDots" width="12" height="12" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#829db8" opacity=".15"/></pattern></defs><rect width="560" height="800" fill="url(#terminalDots)"/>`;
 svg+=[-1,-.75,-.5,-.25,0,.25,.5,.75,1].map(r=>`<line x1="${left}" x2="${right}" y1="${y(r*bound)}" y2="${y(r*bound)}" stroke="#738fad" stroke-dasharray="2 5" opacity=".16"/><text x="9" y="${y(r*bound)+3}" class="axis-percent">${r>0?'+':''}${(r*bound).toFixed(1)}%</text>`).join('');
 svg+=`<line x1="${left}" x2="${right}" y1="${mid}" y2="${mid}" stroke="#a8c9ed" opacity=".5"/><g id="trajectoryPaths">`;
 series.forEach(({s,values},i)=>{let pen=false;const d=values.map((v,j)=>{if(!Number.isFinite(v)){pen=false;return ''}const command=pen?'L':'M';pen=true;return `${command}${x(j/(values.length-1)).toFixed(2)},${y(v).toFixed(2)}`}).join(' '),col=values.filter(Number.isFinite).at(-1)>=0?'var(--buy-blue)':'var(--sell-red)';svg+=`<g data-trajectory="${safe(s.symbol)}" style="color:${col}" role="button" tabindex="0" aria-label="Inspect ${safe(s.symbol)}"><path class="stock-trace" d="${d}"/><path class="trace-packet" d="${d}" style="animation-delay:${i*-.8}s;animation-duration:${9+i%5}s"/><circle class="trace-head" r="2.5" cx="${right}" cy="${y(values.filter(Number.isFinite).at(-1))}"/><path class="trace-hit" d="${d}"/></g>`});svg+='</g><g id="trajectoryLabels">';
 const labels=[...series].sort((a,b)=>b.values.filter(Number.isFinite).at(-1)-a.values.filter(Number.isFinite).at(-1));let prev=top-21;labels.forEach(({s,values},i)=>{const actual=y(values.filter(Number.isFinite).at(-1)),yy=Math.max(top,Math.min(bottom-(labels.length-i-1)*20,Math.max(actual,prev+20)));prev=yy;svg+=`<g data-terminal-stock="${safe(s.symbol)}" class="trajectory-label ${values.filter(Number.isFinite).at(-1)>=0?'buy':'sell'}" tabindex="0" role="button" aria-label="Open ${safe(s.symbol)} chart"><path d="M${right} ${actual}L${right+10} ${yy}H${W-5}" fill="none" stroke="currentColor" opacity=".3"/><rect x="${right+12}" y="${yy-10}" width="98" height="18" rx="2" fill="var(--bg)" stroke="currentColor" stroke-opacity=".25"/><text x="${right+17}" y="${yy+2.5}" fill="currentColor">${safe(s.symbol)}</text></g>`});svg+='</g><text x="51" y="790" class="plot-time">SESSION OPEN</text><text x="350" y="790" class="plot-time">LATEST RECEIVED</text></svg>';root.innerHTML=svg;$$('[data-trajectory]',root).forEach(g=>bindStockPeek(g,g.dataset.trajectory));$$('[data-terminal-stock]',root).forEach(g=>bindStockPeek(g,g.dataset.terminalStock));
}

function bindStockPeek(el,symbol){
 el.onpointerenter=e=>{state.peekKeyboard=false;showStockPeek(symbol,e)};
 el.onpointermove=e=>{state.peekKeyboard=false;showStockPeek(symbol,e)};
 el.onpointerleave=()=>{if(document.activeElement!==el)hideStockPeek()};
 el.onfocus=()=>{state.peekKeyboard=true;const r=el.getBoundingClientRect();showStockPeek(symbol,{clientX:r.right,clientY:r.top+20})};
 el.onblur=hideStockPeek;
 el.onclick=()=>openDetail(symbol);
 el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openDetail(symbol)}if(e.key==='Escape'){hideStockPeek();el.blur()}};
}

function showStockPeek(symbol,event){
 if(state.view!=='overview'||$('#modal')?.open)return;
 const s=stocks().find(v=>v.symbol===symbol);if(!s){hideStockPeek();return}
 state.hoverStock=symbol;if(event)state.hoverPoint={x:event.clientX,y:event.clientY};
 let tip=$('#stockPeek');if(!tip){tip=document.createElement('aside');tip.id='stockPeek';tip.setAttribute('role','tooltip');document.body.append(tip)}
 const m=metric(s),side=s.change>=0?'buy':'sell',status=s.stale?'STALE QUOTE':s.gap?'HISTORY GAP':state.paused?'PAUSED':state.data?.session_state!=='LIVE'?'HISTORICAL SESSION':s.delayed?'PUBLIC · RESEARCH':'AS RECEIVED';
 tip.className='stock-peek '+side;
 tip.innerHTML=`<div class="peek-eyebrow"><span>NSE / EQUITY</span><span>${status}</span></div><div class="peek-identity"><div><strong>${safe(s.symbol)}</strong><small>${safe(s.name)}</small></div><span class="peek-direction">${s.change>=0?'↗':'↘'}</span></div><div class="peek-price"><b>₹${money(s.price)}</b><span>${pct(s.change)}<small>session change</small></span></div><div class="peek-chart">${miniSignalChart(s)}</div><div class="peek-signal"><span>${safe(signal(s))} <small>${state.confirmed?'closed candle':'provisional'}</small></span><b>${m?.score??'—'}<small> / 100</small></b></div><div class="peek-metrics"><span>RSI<b>${m?.rsi??'—'}</b></span><span>REL. VOLUME<b>${m?.rvol??'—'}×</b></span><span>VWAP<b>${m?.vwap==null?'—':money(m.vwap)}</b></span></div><div class="peek-meta"><span>${safe(s.sector)} · ${safe(sourceTitle(s.source))}</span><span>${clock(s.updated_at,true)} IST</span></div><div class="peek-hint">${state.data?.session_state==='LIVE'?'Public candle data · research only':'Stored real candles · historical research'}<span>CLICK FOR FULL CHART ↗</span></div>`;
 const point=state.hoverPoint||{x:innerWidth/2,y:innerHeight/2},r=tip.getBoundingClientRect();
 const left=point.x+22+r.width>innerWidth-12?point.x-r.width-22:point.x+22;
 tip.style.left=Math.max(12,Math.min(innerWidth-r.width-12,left))+'px';tip.style.top=Math.max(12,Math.min(innerHeight-r.height-12,point.y-35))+'px';
 $('#signalTerminal')?.classList.add('has-stock-focus');
 $$('[data-trajectory]').forEach(el=>el.classList.toggle('hovered-trace',el.dataset.trajectory===symbol));
 $$('[data-terminal-stock]').forEach(el=>el.classList.toggle('stock-linked',el.dataset.terminalStock===symbol));
}

function hideStockPeek(){
 state.hoverStock=null;state.peekKeyboard=false;$('#stockPeek')?.remove();$('#signalTerminal')?.classList.remove('has-stock-focus');
 $$('.hovered-trace,.stock-linked').forEach(el=>el.classList.remove('hovered-trace','stock-linked'));
}
window.addEventListener('scroll',()=>{const el=document.activeElement,symbol=el?.dataset?.trajectory||el?.dataset?.terminalStock;if(state.peekKeyboard&&symbol){const r=el.getBoundingClientRect();showStockPeek(symbol,{clientX:r.right,clientY:r.top+20})}else hideStockPeek()},{passive:true});
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideStockPeek()});

// Terminal extensions use only the server's labelled, timestamped snapshots.

function sourceTitle(source){return ({public:'Public candles',yahoo:'Yahoo public candles',scraper:'Public candle source','live-scraper':'Public candle source',exchange:'Received exchange candles',archive:'Stored real candles','previous-session':'Stored real session'})[source]||String(source||'Unavailable')}

function clock(stamp,withDate=false){const n=Number(stamp);if(!Number.isFinite(n)||n<=0)return '—';return new Date(n>1e12?n:n*1000).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',...(withDate?{day:'2-digit',month:'short'}:{}),hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})}

function quoteAge(stamp){const n=Number(stamp);if(!Number.isFinite(n)||n<=0)return 'No timestamp';const seconds=Math.max(0,Date.now()/1000-(n>1e12?n/1000:n));return seconds<60?Math.floor(seconds)+'s old':seconds<3600?Math.floor(seconds/60)+'m old':seconds<86400?Math.floor(seconds/3600)+'h old':Math.floor(seconds/86400)+'d old'}

function sourceBadge(s){const historical=state.data?.session_state!=='LIVE',status=s.status==='failed'?'UNAVAILABLE':s.gap?'GAP':s.stale?'STALE':historical?'HISTORICAL':'RESEARCH';return `<span class="source-pill ${s.stale||s.gap||s.status==='failed'?'is-delayed':''}"><i></i>${safe(sourceTitle(s.source))}<b>${status}</b></span>`}

function getSetup(s){return state.confirmed?s.confirmed_setup:s.setup}

function normalizedSetup(s){const p=getSetup(s)||{};return {...p,type:p.type||p.kind||'unavailable',stop_loss:p.stop_loss??p.stop,risk_reward:p.risk_reward??p.reward_risk,reason:p.reason||p.reasons?.join(' · ')||'Insufficient eligible data for a setup.'}}

function compactPlan(s){const p=normalizedSetup(s);return `<span>${safe(p.grade||'—')} <em>${p.eligible?'ELIGIBLE':'RESEARCH'}</em></span><span>R:R <b>${Number.isFinite(p.risk_reward)?Number(p.risk_reward).toFixed(2):'—'}</b></span>`}

function setupPanel(s){const p=normalizedSetup(s),valid=metric(s)&&p.risk_reward>=1.5&&p.entry!=null&&p.stop_loss!=null;return `<section class="panel setup-panel"><div class="panel-head"><h2>Research setup · ${safe(p.label||p.type.replaceAll('_',' '))}</h2><span class="badge">${safe(p.grade||'—')} · ${state.data?.session_state==='LIVE'?'RESEARCH':'HISTORICAL'}</span></div><div class="setup-levels">${[['Entry reference',valid?p.entry:null],['Invalidation / SL',valid?p.stop_loss:null],['Target 1',valid?p.target1:null],['Target 2',valid?p.target2:null]].map(([label,value])=>`<div><small>${label}</small><strong>₹${money(value)}</strong></div>`).join('')}</div><p>${safe(p.reason||'No qualified setup is available.')} R:R ${valid?Number(p.risk_reward).toFixed(2):'unavailable / filtered'}. ${state.confirmed?'Provisional setup levels are withheld in the confirmed indicator view.':''}</p></section>`}

function comparisonMarkup(s){return `<div class="source-comparison"><div class="health-row"><span>Received source</span><strong>${safe(sourceTitle(s.source))}</strong></div><div class="health-row"><span>Original observation</span><strong>${clock(s.updated_at,true)} IST</strong></div><div class="health-row"><span>Session</span><strong>${safe(state.data?.session_date||'Not reported')} · ${safe(state.data?.session_state||'Unavailable')}</strong></div><div class="health-row"><span>Data quality</span><strong>${s.status==='failed'?'Unavailable':s.stale?'Stale':s.gap?'History gap':'Received'}</strong></div></div>`}

function renderTerminalContext(){
 const root=$('#terminalContext');if(!root||!state.config)return;
 const ss=stocks(),up=ss.filter(s=>s.change>0).length,down=ss.filter(s=>s.change<0).length,total=state.catalogue?.total??state.config.universe.length,ratio=ss.length?up/ss.length*100:0;
 root.innerHTML=`<section class="desk-context"><div class="desk-market"><span class="market-monogram">ZQ</span><div><strong>INDIA EQUITIES</strong><small>NSE · PERSONAL TERMINAL</small></div></div><div class="market-clock"><span id="marketPhase">SESSION</span><strong id="marketCountdown">—</strong><small id="marketNext">Asia / Kolkata</small></div><div class="desk-source"><span class="tiny muted">DATA SOURCE</span><strong style="display:block;margin-top:8px;font-size:11px">${state.data?.session_state==='LIVE'?'Public candles · research':'Stored real session'}</strong><small class="muted tiny">${safe(state.data?.session_date||'Awaiting source data')}</small></div><button id="showSources" class="source-health ${state.modeError?'unavailable':''}" title="Inspect source provenance"><span><i></i><strong>${state.modeError?'SOURCE UNAVAILABLE':state.data?.session_state==='LIVE'?'PUBLIC RESEARCH':'SESSION ARCHIVE'}</strong></span><small>${state.modeError?'Connection needs attention ↗':'View original timestamps and quality ↗'}</small></button></section><section class="desk-breadth"><span><b>${Number(total).toLocaleString('en-IN')}</b> CATALOGUE</span><span><b>${ss.length}</b> IN VIEW</span><span class="buy"><b>${up}</b> ADV</span><div class="breadth-meter" aria-label="Tracked universe advancing and declining"><i style="width:${ratio}%"></i></div><span class="sell"><b>${down}</b> DEC</span><span class="desk-formula">NORMALIZED FORMULA · ${state.confirmed?'CLOSED':'PROVISIONAL'}</span></section><section class="laya-pulse"><button id="pulseOpen" class="pulse-brand"><span>✦</span> LAYA</button><span class="pulse-rule" id="pulseBackend">RULES</span><p>${safe(state.aiPulse?.summary||state.aiPulse?.text||(ss.length?`${ss.length} received companies · ${up} advancing and ${down} declining. Breadth covers this tracked universe only.`:'No price snapshot is available. Source status and the market schedule remain accessible.'))}</p><button id="pulseExplain" aria-label="Open Laya research assistant">ASK LAYA ↗</button></section>`;
 $('#showSources').onclick=showSourceDiagnostics;$('#pulseOpen').onclick=openCopilot;$('#pulseExplain').onclick=openCopilot;renderMarketClock();renderCopilotContext();
}

async function refreshTerminalContext(){
 renderTerminalContext();
 if(!state.scheduleLoading&&Date.now()-(state.scheduleLoadedAt||0)>60000){state.scheduleLoading=true;api('/api/market/schedule').then(d=>{state.marketSchedule=d;state.scheduleLoadedAt=Date.now();renderMarketClock()}).catch(()=>{}).finally(()=>state.scheduleLoading=false)}
 if(!state.catalogueLoading&&!state.catalogue){state.catalogueLoading=true;api('/api/stocks/database?limit=1').then(d=>{state.catalogue=d;renderTerminalContext();renderStatus()}).catch(()=>{}).finally(()=>state.catalogueLoading=false)}
}

function renderMarketClock(){if(!$('#marketPhase'))return;const s=state.marketSchedule||{};$('#marketPhase').textContent=String(s.state||s.phase||'MARKET CLOCK').replaceAll('_',' ');const target=Number(s.target_timestamp),seconds=Number.isFinite(target)&&target>0?Math.max(0,Math.floor(target-Date.now()/1000)):null;$('#marketCountdown').textContent=seconds!==null?`${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds%3600/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`:new Date().toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour12:false});$('#marketNext').textContent=s.target_time_ist?`${s.action==='closes'?'Closes':'Opens'} · ${s.target_time_ist}`:'Regular hours 09:15–15:30 IST'}

function showSourceDiagnostics(){showModal(`<h2>Every observation has a source.</h2><p>This version connects the reference design to Zien Quant’s existing public-candle and real-session archive APIs. Provider observations can be delayed or stale; an animated chart does not establish an exchange stream.</p><div class="health-row"><span>Requested session</span><strong>${state.mode==='previous'?'Explicit stored session':'Automatic exchange session'}</strong></div><div class="health-row"><span>Returned state/date</span><strong>${safe(state.data?.session_state||'Unavailable')} · ${safe(state.data?.session_date||'No date received')}</strong></div><div class="health-row"><span>Available companies</span><strong>${stocks().length}</strong></div><div class="health-row"><span>Unavailable / stale companies</span><strong>${state.data?.unavailable_stocks?.length??0}</strong></div><p>Missing prices and candles are not filled in. Setup levels are filtered below 1:1.5 reward/risk. Archived session research does not create new live signals.</p><p>The preserved <a href="/flow">Flow River ↗</a> uses the existing flow engine. Broker authorization, payments and account recovery are not connected in this repository version.</p>` ,{eyebrow:'SOURCE PROVENANCE'})}

function renderCopilotContext(){const el=$('#aiContext');if(!el)return;const s=selectedStock();el.innerHTML=`<span class="badge">${safe(state.data?.session_state||'UNAVAILABLE')}</span><span>${safe(s?.symbol||'No selected stock')} · ${state.timeframe}m · ${safe(state.data?.session_date||'No received session')}</span>`}

function openCopilot(){state.aiReturnFocus=document.activeElement;$('#copilotDrawer').hidden=false;document.body.classList.add('copilot-open');$('#openCopilot').setAttribute('aria-expanded','true');renderCopilotContext();if(!state.aiMessages.length){state.aiMessages.push({role:'assistant',content:state.data?localBrief(): 'No market snapshot has been received. Retry the data connection before requesting stock analysis.',backend:'rules'});renderAiMessages()}$('#aiMessage').focus()}

function closeCopilot(){document.body.classList.remove('copilot-open');$('#copilotDrawer').hidden=true;$('#openCopilot').setAttribute('aria-expanded','false');state.aiReturnFocus?.focus?.()}

function renderAiMessages(){const container=$('#aiConversation');container.innerHTML=state.aiMessages.map(m=>`<article class="ai-message ${m.role==='user'?'user':'assistant'}"><span>${m.role==='user'?'YOU':m.backend==='ollama'?'LAYA / LOCAL MODEL':'LAYA / RULES'}</span><p>${safe(m.content)}</p></article>`).join('')+(state.aiBusy?'<article class="ai-message assistant"><span>LAYA</span><p class="ai-thinking">Reading the available snapshot…</p></article>':'');container.scrollTop=container.scrollHeight}

async function sendAiMessage(message){const text=String(message||'').trim();if(!text||state.aiBusy)return;state.aiMessages.push({role:'user',content:text});$('#aiMessage').value='';const found=stocks().find(s=>text.toUpperCase().includes(s.symbol));if(found)state.symbol=found.symbol;if(!state.data){state.aiMessages.push({role:'assistant',content:'No received snapshot is available. Retry the connection first.',backend:'rules'});renderAiMessages();return}if(/\b(best|worst|strongest|weakest|top stock|bottom stock|daily rank|ranking)\b/i.test(text)){state.aiMessages.push({role:'assistant',content:dailyRankingBrief(),backend:'rules'});renderAiMessages();return}if(state.mode==='previous'||state.data.session_state!=='LIVE'||state.timeframe!==5||!state.user){state.aiMessages.push({role:'assistant',content:localBrief(/market|breadth|summar|pulse/i.test(text)?null:state.symbol)+(state.user?'':' Interactive local-model chat requires private account sign-in.'),backend:'rules'});renderAiMessages();return}state.aiBusy=true;$('#aiSend').disabled=true;renderAiMessages();try{const r=await api('/api/ai/chat',{method:'POST',body:{message:text,symbol:state.symbol}});state.aiMessages.push({role:'assistant',content:r.reply||r.text||r.summary||'No response was returned.',backend:r.backend});$('#aiBackend').textContent=r.backend==='ollama'?`Local model · ${r.model||'Ollama'}`:'Research assistant · deterministic rules'}catch(e){state.aiMessages.push({role:'assistant',content:e.message,backend:'rules'})}finally{state.aiBusy=false;$('#aiSend').disabled=false;state.aiMessages=state.aiMessages.slice(-20);renderAiMessages()}}

async function analyzeStock(symbol){const target=$('#stockAiText');if(!target)return;if(state.data?.session_state!=='LIVE'||state.mode==='previous'){target.innerHTML=`<span class="badge">RULE-BASED SESSION BRIEFING</span><p>${safe(localBrief(symbol))}</p>`;return}target.textContent='Reading the selected received snapshot…';$('#analyzeStock').disabled=true;const revision=state.revision;try{let r=await api(`/api/ai/analyze?symbol=${encodeURIComponent(symbol)}&timeframe=${state.timeframe}`);if(revision!==state.revision||state.detailSymbol!==symbol||!$('#stockAiText'))return;const show=d=>{$('#stockAiText').innerHTML=`<span class="badge">${d.backend==='ollama'?'VALIDATED LOCAL MODEL':'RULE-BASED BRIEFING'}</span><p>${safe(d.summary||d.text||'No briefing returned.')}</p>${d.ai_pending?'<p class="muted tiny">Local model commentary is processing in the background.</p>':''}`};show(r);if(r.ai_pending){let attempts=0;const poll=async()=>{if(revision!==state.revision||state.detailSymbol!==symbol||!$('#stockAiText'))return;try{r=await api(`/api/ai/analyze?symbol=${encodeURIComponent(symbol)}&timeframe=${state.timeframe}&poll=1`);show(r);if(r.ai_pending&&++attempts<12)setTimeout(poll,5000)}catch(e){if($('#stockAiText'))$('#stockAiText').textContent=e.message}};setTimeout(poll,5000)}}catch(e){if($('#stockAiText'))$('#stockAiText').textContent=e.message}finally{if($('#analyzeStock'))$('#analyzeStock').disabled=false}}

function initTerminalControls(){$('#openCopilot').onclick=openCopilot;$('#closeCopilot').onclick=closeCopilot;$('#aiChatForm').onsubmit=e=>{e.preventDefault();sendAiMessage($('#aiMessage').value)};$$('[data-ai-prompt]').forEach(b=>b.onclick=()=>sendAiMessage(b.dataset.aiPrompt+(b.dataset.aiPrompt.includes('selected stock')?' Selected symbol: '+state.symbol+'.':'')));setInterval(renderMarketClock,1000)}

async function exportSnapshot(){if(!state.user)return showLogin();if(!state.data)return toast('Load a market session before exporting.');const date=state.data.session_date;try{const query=new URL('/api/export','http://workspace.local');query.searchParams.set('timeframe',state.timeframe);if(date)query.searchParams.set('date',date);if(state.data.session_state!=='LIVE')query.searchParams.set('session','previous');const response=await fetch(query.pathname+query.search,{credentials:'same-origin',cache:'no-store'});if(!response.ok){const d=await response.json();if(response.status===401){state.user=null;state.csrf=null;applyBrand()}throw Error(d.detail||d.error||'Export unavailable.')}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`zien-quant-${date||'session'}-${state.timeframe}m.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Displayed session exported')}catch(e){toast(e.message)}}

function drawReceivedChart(area,s){if(!area)return;const bars=chartBars(s),w=Math.max(300,area.clientWidth||300),h=area.clientHeight||285,pad={l:14,r:64,t:20,b:27},vh=state.overlays.volume?46:0,plotH=h-pad.t-pad.b-vh;const values=bars.flatMap(c=>[c.h,c.l]);let low=Math.min(...values),high=Math.max(...values);const spread=high-low||high*.01;low-=spread*.1;high+=spread*.12;const y=p=>pad.t+(high-p)/(high-low)*plotH;const step=(w-pad.l-pad.r)/bars.length;const x=i=>pad.l+(i+.5)*step;const m=metric(s),volMax=Math.max(...bars.map(c=>c.v),1);let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${safe(s.symbol)} ${state.timeframe}-minute OHLC candles with volume. ${bars.length} visible bars."><defs><clipPath id="clip-${area.id}"><rect x="${pad.l}" y="${pad.t}" width="${w-pad.l-pad.r}" height="${plotH}"/></clipPath></defs>`;
for(let i=0;i<5;i++){const price=low+(high-low)*i/4,yy=y(price);svg+=`<line x1="${pad.l}" x2="${w-pad.r}" y1="${yy}" y2="${yy}" stroke="var(--border)" stroke-dasharray="2 5" opacity=".65"/><text x="${w-pad.r+9}" y="${yy+3}" fill="var(--muted)" font-size="8" font-family="monospace">${money(price)}</text>`}
svg+=`<g clip-path="url(#clip-${area.id})">`;if(state.overlays.zones&&m)m.zones.forEach(z=>{if(z.high<low||z.low>high)return;const start=Math.max(0,bars.findIndex(c=>c.t>=z.t));svg+=`<rect x="${x(start)-step/2}" y="${y(z.high)}" width="${w-pad.r-x(start)}" height="${Math.max(2,y(z.low)-y(z.high))}" fill="var(--${z.direction==='bullish'?'green':'red'})" opacity=".09"/><line x1="${x(start)-step/2}" x2="${w-pad.r}" y1="${y(z.low)}" y2="${y(z.low)}" stroke="var(--${z.direction==='bullish'?'green':'red'})" stroke-opacity=".25" stroke-dasharray="3 3"/>`});
if(state.overlays.levels&&m)[[m.support,'green'],[m.resistance,'red']].filter(([p])=>Number.isFinite(p)&&p>0).forEach(([p,c])=>{svg+=`<line x1="${pad.l}" x2="${w-pad.r}" y1="${y(p)}" y2="${y(p)}" stroke="var(--${c})" stroke-dasharray="5 4" opacity=".5"/>`});
if(state.overlays.vwap){let volume=0,pv=0,day='',points=[];s.candles.forEach(c=>{const date=new Date(c.t*1000).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});if(date!==day){day=date;volume=0;pv=0}volume+=c.v;pv+=(c.h+c.l+c.c)/3*c.v;const i=bars.indexOf(c);if(i>=0&&volume)points.push(`${x(i)},${y(pv/volume)}`)});svg+=`<polyline points="${points.join(' ')}" fill="none" stroke="var(--purple)" stroke-width="1.3" opacity=".9"/>`}
bars.forEach((c,i)=>{const col=c.c>=c.o?'green':'red',body=Math.max(1.5,Math.abs(y(c.o)-y(c.c)));svg+=`<line x1="${x(i)}" x2="${x(i)}" y1="${y(c.h)}" y2="${y(c.l)}" stroke="var(--${col})" stroke-width="1"/><rect x="${x(i)-Math.max(2,step*.58)/2}" y="${Math.min(y(c.o),y(c.c))}" width="${Math.max(2,step*.58)}" height="${body}" rx=".5" fill="var(--${col})" opacity="${c.closed?'.9':'.65'}"/>`});svg+='</g>';
if(state.overlays.volume)bars.forEach((c,i)=>{const hh=c.v/volMax*(vh-6);svg+=`<rect x="${x(i)-step*.3}" y="${h-pad.b-hh}" width="${Math.max(1,step*.6)}" height="${hh}" fill="var(--${c.c>=c.o?'green':'red'})" opacity=".22"/>`});
const last=bars[bars.length-1];if(last){svg+=`<line x1="${pad.l}" x2="${w-pad.r}" y1="${y(last.c)}" y2="${y(last.c)}" stroke="var(--green)" stroke-dasharray="3 4" opacity=".5"/><rect x="${w-pad.r+3}" y="${y(last.c)-9}" width="58" height="18" rx="3" fill="var(--green)"/><text x="${w-pad.r+32}" y="${y(last.c)+3}" text-anchor="middle" fill="var(--bg)" font-size="8" font-family="monospace">${money(last.c)}</text>`}
[0,.25,.5,.75,1].forEach(t=>{const i=Math.round(t*(bars.length-1)),c=bars[i];if(c)svg+=`<text x="${x(i)}" y="${h-8}" fill="var(--subtle)" font-size="8" text-anchor="middle" font-family="monospace">${new Date(c.t*1000).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:false})}</text>`});svg+='</svg>';const old=$('svg',area);if(old)old.outerHTML=svg;else area.innerHTML=svg;area.dataset.barCount=bars.length;}

function drawChart(area,s){if(!area)return;if(!s.candles?.length||!chartBars(s).length){area.innerHTML=`<div class="chart-empty">${s.historyLoading?'Loading received candles…':safe(s.historyError||'Full candle history is unavailable for the selected session.')}</div>`;return}drawReceivedChart(area,s)}

function localBrief(symbol){const s=stocks().find(v=>v.symbol===symbol);if(s){const m=metric(s),p=normalizedSetup(s);return `${s.symbol} · ${state.data?.session_date||'Received session'} · ${state.timeframe}m\nPrice ₹${money(s.price)} (${pct(s.change)}). Directional score ${m?.score??'unavailable'}, RSI ${m?.rsi??'unavailable'}, RVOL ${m?.rvol??'unavailable'}×. ${p.reason||'No qualified setup is available.'} ${p.risk_reward>=1.5?'Reward/risk '+p.risk_reward.toFixed(2)+'.':'The reward/risk filter withholds actionable levels.'} This is a deterministic explanation of the selected received observation.`}const ss=stocks(),bull=ss.filter(s=>signal(s)==='Bullish').length,bear=ss.filter(s=>signal(s)==='Bearish').length;return `${ss.length} received companies: ${bull} bullish, ${bear} bearish and ${ss.length-bull-bear} neutral or unavailable. This describes the tracked universe for ${state.data?.session_date||'the received session'}, rather than an official market index. Public candles can be delayed. Ask for a tracked stock’s setup or inspect its chart.`}

async function startWorkspace(){
 $('#closeModal').onclick=dismissDialog;$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dismissDialog()}};$('#searchButton').onclick=showSearch;$('#account').onclick=showLogin;$('#autoMode').onclick=()=>setMode('live');$('#previousMode').onclick=()=>setMode('previous');$('#mobileMenu').onclick=()=>document.body.classList.toggle('menu-open');$('#pause').onclick=()=>{state.paused=!state.paused;renderStatus();if(!state.paused)refresh(true)};$('#theme').onclick=()=>{document.body.classList.toggle('light');store('zien-light',document.body.classList.contains('light'));$('#theme span').textContent=document.body.classList.contains('light')?'Switch to dark theme':'Switch to light theme';drawAll()};$('#motion').onclick=()=>{state.reduced=!state.reduced;document.body.classList.toggle('reduced',state.reduced);store('zien-reduced',state.reduced);syncMotion();toast(state.reduced?'Reduced motion enabled':'Ambient motion enabled')};$('#info').onclick=showSourceDiagnostics;$('#export').onclick=exportSnapshot;historyView.bind();document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch()}if(e.key==='Escape'&&document.body.classList.contains('history-panel-open'))historyView.close();if(e.key==='Escape'&&!$('#copilotDrawer').hidden)closeCopilot()});window.addEventListener('resize',drawAll);document.addEventListener('visibilitychange',()=>{syncMotion();if(!document.hidden&&!state.paused)refresh()});if(stored('zien-light',false)){document.body.classList.add('light');$('#theme span').textContent='Switch to dark theme'}document.body.classList.toggle('reduced',state.reduced);bindCommon();$('#mainContent').innerHTML='<div class="loading">Connecting to your market workspace…</div>';initTerminalControls();await bootstrap();const initial=location.hash.slice(1);if(initial&&names[initial])navigate(initial)
}
await startWorkspace();

function candleKey(symbol){return [state.mode,state.data?.session_date,state.timeframe,symbol].join('|')}
async function hydrateStock(symbol){
 const key=candleKey(symbol),revision=state.revision,s=stocks().find(v=>v.symbol===symbol);if(!s)return;
 const cached=candleCache.get(key);if(cached&&(state.data?.session_state!=='LIVE'||Date.now()-cached.loadedAt<30000)){s.candles=cached.candles;return}
 if(pendingCandles.has(key))return pendingCandles.get(key);s.historyLoading=true;
 const date=state.data?.session_date,historical=state.data?.session_state!=='LIVE';
 const task=(async()=>{try{
  const query=new URL('/api/stock','http://workspace.local');query.searchParams.set('symbol',symbol);query.searchParams.set('timeframe',state.timeframe);if(historical&&date)query.searchParams.set('date',date);
  const r=await api(query.pathname+query.search);if(revision!==state.revision||key!==candleKey(symbol))return;
  let cc=normalizeCandles(r.candles);if(date)cc=cc.filter(c=>new Date(c.t*1000).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})===date);
  if(!cc.length)throw Error('No received candle history matches the selected session.');
  candleCache.set(key,{candles:cc,loadedAt:Date.now()});const current=stocks().find(v=>v.symbol===symbol);if(current){current.candles=cc;current.historyLoading=false;current.historyError=null}
  if(state.symbol===symbol)renderMainChart();if(state.detailSymbol===symbol)renderDetailChart();
 }catch(e){if(revision!==state.revision)return;const current=stocks().find(v=>v.symbol===symbol);if(current){current.historyError=e.message;current.historyLoading=false}if($('#detailChart'))renderDetailChart();if($('#mainChart'))renderMainChart()}finally{pendingCandles.delete(key)}})();
 pendingCandles.set(key,task);return task;
}
